import { Redis } from '@upstash/redis';

const redis = Redis.fromEnv();

async function batchUpdate() {
  const p = redis.pipeline();

  // Queue commands - they're NOT executed yet
  p.set('user:1:name', 'Alice');
  p.set('user:1:score', 100);
  p.incr('total_users');
  p.expire('session:abc', 3600);

  // Execute all as a single HTTP request
  const [setResult1, setResult2, newCount, expireResult] = await p.exec<
    [string, string, number, number]
  >();

  console.log(newCount); // current total_users count
}

