import { Redis } from '@upstash/redis';

const redis = Redis.fromEnv();

// Enable auto-pipelining: concurrent commands are automatically batched into
// single HTTP requests, reducing latency without manual pipeline management
redis.enableAutoPipelining();

async function main() {
  // These run 'concurrently' so auto-pipeline batches them into one HTTP request
  const [a, b, c] = await Promise.all([
    redis.set('key1', 'value1'),
    redis.set('key2', 'value2'),
    redis.get('key1'),
  ]);

  console.log(a, b, c);
}

main();

